Name: PcAnywhere TCP Service Discovery Description: Discover active pcAnywhere services through TCP', 'Author' => 'hdm', 'License' => MSF_LICENSE ) register_options( [ Opt::RPORT(5631) ] ) end def run_host(ip) begin connect sock.put("\x00\x00\x00\x00") res = sock.get_once(-1, 15) if not (res and res.index("Please press <Enter>")) disconnect return end =begin sock.put( "\x6f\x06\xfe" ) res = sock.get_once(-1, 15) sock.put("\x6f\x61\xff\x09\x00\x07\x00\x00\x01\xff\x00\x00\x07\x00") res = sock.get_once(-1, 15) sock.put("\x6f\x62\x00\x02\x00\x00\x00") res = sock.get_once(-1, 15) print_status(Rex::Text.to_hex_dump(res)) =end report_service(:host => rhost, :port => rport, :name => "pcanywhere_data", :info => "") print_good("#{rhost}:#{rport} pcAnywhere data service") rescue ::Rex::ConnectionError, ::EOFError, ::Errno::ECONNRESET rescue ::Exception => e print_error("#{rhost}:#{rport} Error: #{e.class} #{e} #{e.backtrace}

module_path: auxiliary/scanner/pcanywhere/pcanywhere_udp
PcAnywhere UDP Service Discovery

Name: PcAnywhere UDP Service Discovery Description: Discover active pcAnywhere services through UDP', 'Author' => 'hdm', 'License' => MSF_LICENSE, 'References' => [ ['URL', 'http://www.unixwiz.net/tools/pcascan.txt'] ] ) register_options( [ Opt::RPORT(5632) ] ) end def scanner_prescan(batch) print_status("Sending pcAnywhere discovery requests to #{batch[0]}->#{batch[-1]} (#{batch.length} hosts)") @results = {} end def scan_host(ip) scanner_send("NQ", ip, datastore['RPORT']) scanner_send("ST", ip, datastore['RPORT']) end def scanner_postscan(batch) @results.keys.each do |ip| data = @results[ip] info = "" if data[:name] info << "Name: #{data[:name]} " end if data[:stat] info << "- #{data[:stat]} " end if data[:caps] info << "( #{data[:caps]} ) " end report_service(:host => ip, :port => datastore['RPORT'], :proto => 'udp', :name => "pcanywhere_stat", :info => info) report_note(:host => ip, :port => datastore['RPORT'], :proto => 'udp', :name => "pcanywhere_stat", :update => :unique, :ntype => "pcanywhere.status", :data => data) print_good("#{ip}:#{datastore['RPORT']} #{info}") end end def scanner_process(data, shost, sport) case data when /^NR(........................)(........)/ name = $1.dup caps = $2.dup name = name.gsub(/_+$/, '').gsub("\x00", '').strip caps = caps.gsub(/_+$/, '').gsub("\x00", '').strip @results[shost] ||= {} @results[shost][:name] = name @results[shost][:caps] = caps when /^ST(.+)/ @results[shost] ||= {} buff = $1.dup stat = 'Unknown' if buff[2, 1].unpack("C")[0] == 67 stat = "Available" end if buff[2, 1].unpack("C")[0] == 11 stat = "Busy" end @results[shost][:stat] = stat else print_error("#{shost} Unknown: #{data.inspect}

