module_path: auxiliary/scanner/snmp/aix_version
AIX SNMP Scanner

Name: AIX SNMP Scanner Description: AIX SNMP scanner auxiliary module.', 'Author' => [ 'Ramon de C Valle', 'Adriano Lima <adriano[at]risesecurity.org>', ], 'License' => MSF_LICENSE, 'Notes' => { 'Stability' => [CRASH_SAFE], 'SideEffects' => [], 'Reliability' => [] } ) end def run_host(ip) snmp = connect_snmp value = snmp.get_value('sysDescr.0') unless value =~ /AIX/ print_error("#{ip} system is not AIX: #{value}") return end value = value.split("\n") description = value[0].strip value = value[2].split(':') value = value[1].strip value = value.split('.') value[0] = value[0].to_i value[1] = value[1].to_i value[2] = value[2].to_i value[3] = value[3].to_i version = "#{value[0]}.#{value[1]}.#{value[2]}.#{value[3]}" report_note( host: ip, proto: 'udp', sname: 'snmp', port: datastore['RPORT'], type: 'AIX', data: { version: version } ) status = "#{ip} (#{description}) is running: " status << "IBM AIX Version #{value[0]}.#{value[1]}.#{value[3]} " status << "(#{version})" print_status(status) rescue ::Rex::ConnectionError, ::SNMP::RequestTimeout # No need to make noise about timeouts rescue ::SNMP::UnsupportedVersion => e vprint_error(e.message) rescue ::Interrupt raise $ERROR_INFO rescue StandardError => e print_error("#{ip} #{e.class}, #{e.message}

module_path: auxiliary/scanner/snmp/snmp_enumshares
SNMP Windows SMB Share Enumeration

Name: SNMP Windows SMB Share Enumeration Description: This module will use LanManager OID values to enumerate SMB shares on a Windows system via SNMP', 'Author' => ['tebo[at]attackresearch.com'], 'License' => MSF_LICENSE, 'Notes' => { 'Stability' => [CRASH_SAFE], 'SideEffects' => [], 'Reliability' => [] } ) end def run_host(ip) snmp = connect_snmp share_tbl = [ '1.3.6.1.4.1.77.1.2.27.1.1', '1.3.6.1.4.1.77.1.2.27.1.2', '1.3.6.1.4.1.77.1.2.27.1.3' ] @shares = [] if snmp.get_value('sysDescr.0') =~ /Windows/ snmp.walk(share_tbl) do |entry| @shares << entry.collect(&:value) end end disconnect_snmp return if @shares.empty? print_good("#{ip} #{@shares.map { |x| "\n\t#{x[0]} - #{x[2]} (#{x[1]})" }.join}") report_note( host: ip, proto: 'udp', port: datastore['RPORT'], sname: 'snmp', type: 'smb.shares', data: { shares: @shares }, update: :unique_data ) rescue SNMP::ParseError print_error("#{ip} Encountered an SNMP parsing error while trying to enumerate the host.") rescue ::Rex::ConnectionError, ::SNMP::RequestTimeout => e vprint_error("#{ip} #{e.message}") rescue ::SNMP::UnsupportedVersion => e vprint_error("#{ip} #{e.message}") rescue ::Interrupt raise $ERROR_INFO rescue StandardError => e print_error("#{ip} Unknown error: #{e.class} #{e}

module_path: auxiliary/scanner/vnc/vnc_none_auth
VNC Authentication None Detection

Name: VNC Authentication None Detection Description: Detect VNC servers that support the "None" authentication method.', 'References' => [ ['CVE', '2006-2369'], # a related instance where "None" could be offered and used when not configured as allowed. ['URL', 'https://en.wikipedia.org/wiki/RFB'], ['URL', 'https://en.wikipedia.org/wiki/Vnc'], ], 'Author' => [ 'Matteo Cantoni <goony[at]nothink.org>', 'jduck' ], 'License' => MSF_LICENSE ) register_options( [ Opt::RPORT(5900) ] ) end def run_host(target_host) connect vnc = Rex::Proto::RFB::Client.new(sock, allow_none: true) unless vnc.handshake print_error("#{target_host}:#{rport} - Handshake failed: #{vnc.error}") return end ver = "#{vnc.majver}.#{vnc.minver}" print_status("#{target_host}:#{rport} - VNC server protocol version: #{ver}") svc = report_service( host: rhost, port: rport, proto: 'tcp', name: 'vnc', info: "VNC protocol version #{ver}" ) type = vnc.negotiate_authentication unless type print_error("#{target_host}:#{rport} - Auth negotiation failed: #{vnc.error}") return end # Show the allowed security types sec_type = [] vnc.auth_types.each do |t| sec_type << Rex::Proto::RFB::AuthType.to_s(t) end print_status("#{target_host}:#{rport} - VNC server security types supported: #{sec_type.join(', ')}") if (vnc.auth_types.include? Rex::Proto::RFB::AuthType::None) print_good("#{target_host}:#{rport} - VNC server security types includes None, free access!") report_vuln( { host: rhost, service: svc, name: name, info: "Module #{fullname} identified the VNC 'none' security type: #{sec_type.join(', ')}
